def add(id,doc,line,kind,text,word,scope,time='none',material=False,paths=(),deps=()):
    name={'04':'pi-04-ADVERSARIAL-VERIFICATION.md','05':'pi-05-OPERATIONS-AND-HANDOFF.md'}[doc]
    assert word in docs[name][line-1],(id,line,word,docs[name][line-1])
    assert re.fullmatch(r'C(18[1-9]|19[0-9]|20[0-9]|21[0-9]|22[0-9]|230)',id),id
    rows.append(dict(id=id,doc=name,loc=f'L{line}',kind=kind,text=text,strongestWording=word,scope=scope,timeContext=time,material=material,citedPaths=list(paths),deps=list(deps)))
